const WORKSPACE_HTML = "<div class=\"app-layout\">\n    <!-- ==================== LEFT SIDEBAR (CLEAN CANVA-STYLE SHELL) ==================== -->\n    <aside class=\"sidebar\">\n      <div>\n        <div class=\"brand\">\n          <div class=\"brand-orb\">QG</div>\n          <div>\n            <h1>Quantum Guard</h1>\n            <div class=\"brand-sub\">NIST FIPS 203 \u00b7 204 \u00b7 205</div>\n          </div>\n        </div>\n\n        <nav class=\"nav-menu\" id=\"main-nav\">\n          <div class=\"nav-label\">Workspace</div>\n          <button class=\"nav-btn active\" data-tab=\"pipeline\">\n            <span class=\"nav-dot\"></span> Live Agent Flow\n          </button>\n          <button class=\"nav-btn\" data-tab=\"overview\">\n            <span class=\"nav-dot\"></span> Executive Overview\n          </button>\n          <button class=\"nav-btn\" data-tab=\"discovery\">\n            <span class=\"nav-dot\"></span> Discovery &amp; Mosca Risk\n          </button>\n          <button class=\"nav-btn\" data-tab=\"migration\">\n            <span class=\"nav-dot\"></span> Migration, PKI &amp; Vault\n          </button>\n          <button class=\"nav-btn\" data-tab=\"hybrid\">\n            <span class=\"nav-dot\"></span> Hybrid Lab &amp; Benchmarks\n          </button>\n        </nav>\n      </div>\n\n      <div class=\"sidebar-footer\">\n        <div class=\"runtime-pill\" id=\"cap-text\">\n          Checking OpenSSL 3.5+ PQC runtime...\n        </div>\n        <div style=\"display:flex; gap:6px;\">\n          <button class=\"btn btn-red btn-sm\" style=\"flex:1;\" id=\"btn-reset-demo\" onclick=\"resetDemoUI()\">Reset</button>\n          <button class=\"btn btn-outline btn-sm\" style=\"flex:1;\" onclick=\"openProtectedEnterpriseReport()\">&#128274; PDF Report</button>\n        </div>\n      </div>\n    </aside>\n\n    <!-- ==================== MAIN WORKSPACE ==================== -->\n    <main class=\"workspace\">\n      <!-- Degraded Capability Warning (hidden when OpenSSL 3.5+ is active) -->\n      <div class=\"cap-degraded\" id=\"cap-degraded\" style=\"display:none; margin-bottom:16px; border-radius:12px;\"></div>\n\n      <!-- SaaS Command Header: Target Scanner + Launch Agent + Supabase & RBAC Auth -->\n      <div class=\"aurora-hero\">\n        <div style=\"display:flex; align-items:center; gap:10px; flex:1; min-width:300px;\">\n          <input\n            type=\"text\"\n            id=\"saas-target-input\"\n            placeholder=\"Enter target domain to scan (e.g. cloudflare.com, google.com, veerbhanushali.in)...\"\n            style=\"max-width:420px; border-color:var(--purple);\"\n            onkeydown=\"if(event.key==='Enter')runSaaSTargetScan()\"\n          />\n          <button class=\"btn btn-purple\" id=\"btn-saas-scan\" onclick=\"runSaaSTargetScan()\">&#127760; Scan Target</button>\n          <button class=\"btn btn-blue\" id=\"btn-guided-demo\" onclick=\"runGuidedDemo()\">&#10024; Full Enterprise Demo</button>\n        </div>\n        <div class=\"hero-actions\">\n          <span class=\"badge sev-ok\" id=\"supabase-badge\" title=\"Connected to Supabase PostgreSQL (ap-south-1)\">&#9679; Supabase Cloud</span>\n          <a class=\"btn btn-outline btn-sm\" id=\"btn-cbom-download\" href=\"/api/cbom/1\" target=\"_blank\">&#11015; CBOM</a>\n          <div id=\"auth-bar-area\" style=\"display:inline-flex; align-items:center; gap:6px;\">\n            <button class=\"btn btn-purple btn-sm\" id=\"btn-open-auth\" onclick=\"openAuthModal('login')\">&#128274; Sign In / Sign Up</button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Guided Demo Progress Strip -->\n      <div class=\"demo-progress-bar\" id=\"demo-banner\" style=\"border-radius:12px; margin-bottom:20px;\">\n        <span id=\"demo-step-text\">Agent Pipeline Running...</span>\n        <span id=\"demo-step-pct\">0%</span>\n      </div>\n\n      <!-- ==================== PAGE 1 (DEFAULT): LIVE AGENT FLOW ==================== -->\n      <section class=\"tab-section active\" id=\"tab-pipeline\">\n        <div class=\"agent-stage-wrapper\">\n          <!-- Ambient Glowing Orbs Behind Glass Stage -->\n          <div class=\"ambient-orb orb-1\"></div>\n          <div class=\"ambient-orb orb-2\"></div>\n          <div class=\"ambient-orb orb-3\"></div>\n\n          <div class=\"dag-header-row\">\n            <div class=\"dag-title-group\">\n              <span style=\"font-size:1.35rem; color:#64748b;\">&#10050;</span>\n              <h2>Agent Execution Graph (DAG with Feedback Loop)</h2>\n            </div>\n            <div class=\"stage-status-pill\">\n              <span class=\"pulse-dot purple\" id=\"graph-pulse-dot\"></span>\n              <span id=\"graph-stage-label\">Agent Ready \u2014 Click \"Launch Live Agent\" to stream live PQC discovery &amp; migration</span>\n            </div>\n          </div>\n\n          <div class=\"dag-legend-bar\">\n            <div class=\"dag-legend-pills\">\n              <span class=\"dag-legend-pill\"><i class=\"dot green\"></i> Completed</span>\n              <span class=\"dag-legend-pill\"><i class=\"dot blue\"></i> Active Working</span>\n              <span class=\"dag-legend-pill\"><i class=\"dot purple\"></i> Feedback Loop</span>\n              <span class=\"dag-legend-pill\"><i class=\"dot red\"></i> HNDL / Vulnerable</span>\n              <span class=\"dag-legend-pill\"><i class=\"dot pending\"></i> Pending</span>\n            </div>\n            <div style=\"display:flex; gap:8px;\">\n              <button class=\"btn btn-purple btn-sm\" onclick=\"runGuidedDemo()\">&#9654; Run Full DAG Pipeline</button>\n              <button class=\"btn btn-blue btn-sm\" onclick=\"triggerScan('before')\">Scan Only</button>\n              <button class=\"btn btn-green btn-sm\" onclick=\"applyMigrationPlan()\">Apply PQC Auto-Fix</button>\n            </div>\n          </div>\n\n          <!-- Spacious Dotted Grid DAG Canvas (7 Nodes + Curved Purple Feedback Loop) -->\n          <div class=\"dag-canvas-box\">\n            <svg class=\"dag-svg\" viewBox=\"0 0 1160 390\" xmlns=\"http://www.w3.org/2000/svg\">\n              <defs>\n                <!-- Arrowheads matching state colors -->\n                <marker id=\"arrow-pending\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                  <path d=\"M 0 1.5 L 8.5 5 L 0 8.5 z\" fill=\"#cbd5e1\" />\n                </marker>\n                <marker id=\"arrow-active\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                  <path d=\"M 0 1.5 L 8.5 5 L 0 8.5 z\" fill=\"#2563eb\" />\n                </marker>\n                <marker id=\"arrow-feedback\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                  <path d=\"M 0 1.5 L 8.5 5 L 0 8.5 z\" fill=\"#7c3aed\" />\n                </marker>\n                <marker id=\"arrow-alert\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                  <path d=\"M 0 1.5 L 8.5 5 L 0 8.5 z\" fill=\"#ef4444\" />\n                </marker>\n                <marker id=\"arrow-complete\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                  <path d=\"M 0 1.5 L 8.5 5 L 0 8.5 z\" fill=\"#10b981\" />\n                </marker>\n              </defs>\n\n              <!-- ==================== DIRECTED S-CURVE EDGES ==================== -->\n              <!-- 01 -> 02 and 01 -> 03 -->\n              <path id=\"dag-edge-1-2\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 205 182 C 250 182, 240 96, 282 96\" marker-end=\"url(#arrow-pending)\" />\n              <path id=\"dag-edge-1-3\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 205 208 C 250 208, 240 294, 282 294\" marker-end=\"url(#arrow-pending)\" />\n\n              <!-- Curved Feedback Loop: 03 (Reflect Gate) -> 02 (TLS & Code Recon) -->\n              <path id=\"dag-edge-loop\" class=\"dag-edge state-feedback\" fill=\"none\" d=\"M 358 260 C 312 220, 312 170, 358 134\" marker-end=\"url(#arrow-feedback)\" />\n              <!-- Feedback Loop Pill Badge -->\n              <g transform=\"translate(222, 181)\" onclick=\"selectDagNode(3)\" onmouseenter=\"selectDagNode(3)\" style=\"cursor:pointer;\">\n                <rect class=\"feedback-pill-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"114\" height=\"26\" rx=\"13\" />\n                <text class=\"feedback-pill-text\" x=\"57\" y=\"16\" text-anchor=\"middle\">&#8635; FEEDBACK LOOP</text>\n              </g>\n\n              <!-- 02 -> 04 and 03 -> 04 -->\n              <path id=\"dag-edge-2-4\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 461 96 C 502 96, 492 182, 532 182\" marker-end=\"url(#arrow-pending)\" />\n              <path id=\"dag-edge-3-4\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 461 294 C 502 294, 492 208, 532 208\" marker-end=\"url(#arrow-pending)\" />\n\n              <!-- 04 -> 05 and 04 -> 06 -->\n              <path id=\"dag-edge-4-5\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 711 182 C 745 182, 735 96, 767 96\" marker-end=\"url(#arrow-pending)\" />\n              <path id=\"dag-edge-4-6\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 711 208 C 745 208, 735 294, 767 294\" marker-end=\"url(#arrow-pending)\" />\n\n              <!-- 05 -> 07 and 06 -> 07 -->\n              <path id=\"dag-edge-5-7\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 946 96 C 966 96, 958 182, 977 182\" marker-end=\"url(#arrow-pending)\" />\n              <path id=\"dag-edge-6-7\" class=\"dag-edge state-pending\" fill=\"none\" d=\"M 946 294 C 966 294, 958 208, 977 208\" marker-end=\"url(#arrow-pending)\" />\n\n              <!-- ==================== 7 DAG NODES ==================== -->\n              <!-- NODE 01: Scope & TLS Init -->\n              <g id=\"dag-node-1\" class=\"dag-node state-pending\" transform=\"translate(30, 161)\" onclick=\"selectDagNode(1)\" onmouseenter=\"selectDagNode(1)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">AGENT</text>\n                <text id=\"dag-meta-1\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">Ready</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">01. Scope &amp; Init</text>\n              </g>\n\n              <!-- NODE 02: Tool Recon (5 TLS Ports + AST) -->\n              <g id=\"dag-node-2\" class=\"dag-node state-pending\" transform=\"translate(286, 62)\" onclick=\"selectDagNode(2)\" onmouseenter=\"selectDagNode(2)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">TOOL</text>\n                <text id=\"dag-meta-2\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">5 Ports</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">02. Tool Recon</text>\n              </g>\n\n              <!-- NODE 03: Reflect Gate (Self-Healing AST & Cert Gate) -->\n              <g id=\"dag-node-3\" class=\"dag-node state-pending selected\" transform=\"translate(286, 260)\" onclick=\"selectDagNode(3)\" onmouseenter=\"selectDagNode(3)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">DECISION</text>\n                <text id=\"dag-meta-3\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">17 Rules</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">03. Reflect Gate</text>\n              </g>\n\n              <!-- NODE 04: Observation & CycloneDX CBOM -->\n              <g id=\"dag-node-4\" class=\"dag-node state-pending\" transform=\"translate(536, 161)\" onclick=\"selectDagNode(4)\" onmouseenter=\"selectDagNode(4)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">AGENT</text>\n                <text id=\"dag-meta-4\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">CBOM 1.6</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">04. Observation</text>\n              </g>\n\n              <!-- NODE 05: Threat Intel & PQC PKI CA -->\n              <g id=\"dag-node-5\" class=\"dag-node state-pending\" transform=\"translate(771, 62)\" onclick=\"selectDagNode(5)\" onmouseenter=\"selectDagNode(5)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">PKI CA</text>\n                <text id=\"dag-meta-5\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">ML-DSA</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">05. PQC PKI &amp; Intel</text>\n              </g>\n\n              <!-- NODE 06: Deep Probe & Hybrid Auto-Migrate -->\n              <g id=\"dag-node-6\" class=\"dag-node state-pending\" transform=\"translate(771, 260)\" onclick=\"selectDagNode(6)\" onmouseenter=\"selectDagNode(6)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"175\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"22\" y1=\"0\" x2=\"128\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"20\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"30\" y=\"26\">TOOL</text>\n                <text id=\"dag-meta-6\" class=\"dag-meta-lbl\" x=\"157\" y=\"26\" text-anchor=\"end\">ML-KEM</text>\n                <text class=\"dag-title-lbl\" x=\"18\" y=\"50\">06. Deep Migrate</text>\n              </g>\n\n              <!-- NODE 07: Risk Scorer & Quantum Verifier -->\n              <g id=\"dag-node-7\" class=\"dag-node state-pending\" transform=\"translate(981, 161)\" onclick=\"selectDagNode(7)\" onmouseenter=\"selectDagNode(7)\">\n                <rect class=\"dag-node-rect\" fill=\"#ffffff\" x=\"0\" y=\"0\" width=\"155\" height=\"68\" rx=\"12\" />\n                <line class=\"dag-top-bar\" x1=\"20\" y1=\"0\" x2=\"115\" y2=\"0\" />\n                <circle class=\"dag-dot\" cx=\"18\" cy=\"23\" r=\"4\" />\n                <text class=\"dag-kind-lbl\" x=\"28\" y=\"26\">AGENT</text>\n                <text id=\"dag-meta-7\" class=\"dag-meta-lbl\" x=\"140\" y=\"26\" text-anchor=\"end\">--%</text>\n                <text class=\"dag-title-lbl\" x=\"16\" y=\"50\">07. Risk Scorer</text>\n              </g>\n            </svg>\n          </div>\n\n          <!-- Selected Node Inspector Bar (Exact Match to Reference Bottom Bar) -->\n          <div class=\"dag-inspector-bar\">\n            <div class=\"dag-inspector-left\">\n              <div class=\"dag-inspector-lbl\">Selected<br />Node:</div>\n              <div class=\"dag-inspector-name\" id=\"dag-selected-name\">03. Reflect Gate</div>\n            </div>\n            <div class=\"dag-inspector-divider\"></div>\n            <div class=\"dag-inspector-desc\" id=\"dag-selected-desc\">\n              Self-healing gate: detects classical RSA/ECDHE handshakes &amp; 17 AST rules. Loops back to trigger targeted PQC probe.\n            </div>\n            <div class=\"dag-inspector-kind\" id=\"dag-selected-kind\">Kind: DECISION</div>\n          </div>\n\n          <!-- SaaS Target Scan Result & Login-Gated Report Bar -->\n          <div id=\"saas-target-result-bar\" style=\"display:none; position:relative; z-index:3; margin-top:12px;\"></div>\n\n          <!-- 5 Live Enterprise Service Pills -->\n          <div class=\"endpoint-nodes-strip\">\n            <div class=\"endpoint-pill-card\" id=\"ep-card-legacy-web\" onclick=\"switchTab('discovery')\">\n              <div class=\"ep-name\">\n                <span>legacy-web (:9441)</span>\n                <span class=\"badge sev-low\" id=\"ep-badge-legacy-web\">IDLE</span>\n              </div>\n              <div class=\"ep-profile\" id=\"ep-prof-legacy-web\">legacy_tls12_rsa</div>\n            </div>\n\n            <div class=\"endpoint-pill-card\" id=\"ep-card-customer-api\" onclick=\"switchTab('discovery')\">\n              <div class=\"ep-name\">\n                <span>customer-api (:9442)</span>\n                <span class=\"badge sev-low\" id=\"ep-badge-customer-api\">IDLE</span>\n              </div>\n              <div class=\"ep-profile\" id=\"ep-prof-customer-api\">tls13_ecdhe_ecdsa</div>\n            </div>\n\n            <div class=\"endpoint-pill-card\" id=\"ep-card-payments-core\" onclick=\"switchTab('discovery')\">\n              <div class=\"ep-name\">\n                <span>payments-core (:9443)</span>\n                <span class=\"badge sev-low\" id=\"ep-badge-payments-core\">IDLE</span>\n              </div>\n              <div class=\"ep-profile\" id=\"ep-prof-payments-core\">tls13_ecdhe_rsa (15y)</div>\n            </div>\n\n            <div class=\"endpoint-pill-card\" id=\"ep-card-hr-records\" onclick=\"switchTab('discovery')\">\n              <div class=\"ep-name\">\n                <span>hr-records (:9444)</span>\n                <span class=\"badge sev-low\" id=\"ep-badge-hr-records\">IDLE</span>\n              </div>\n              <div class=\"ep-profile\" id=\"ep-prof-hr-records\">tls13_ecdhe_ecdsa (25y)</div>\n            </div>\n\n            <div class=\"endpoint-pill-card\" id=\"ep-card-pqc-pilot\" onclick=\"switchTab('discovery')\">\n              <div class=\"ep-name\">\n                <span>pqc-pilot (:9445)</span>\n                <span class=\"badge sev-low\" id=\"ep-badge-pqc-pilot\">IDLE</span>\n              </div>\n              <div class=\"ep-profile\" id=\"ep-prof-pqc-pilot\">hybrid_mlkem_ecdsa</div>\n            </div>\n          </div>\n\n          <!-- Live Telemetry Feed -->\n          <div style=\"position:relative; z-index:3; margin-top:10px;\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;\">\n              <b style=\"font-size:0.78rem; color:var(--text-secondary);\">Live Agent Activity Stream</b>\n              <span style=\"font-size:0.72rem; color:var(--text-muted);\">Hover or click any DAG node above to inspect</span>\n            </div>\n            <div class=\"telemetry-feed\" id=\"graph-telemetry-feed\">\n              <div class=\"telemetry-item purple\">\n                <span><b>[READY]</b> Click \"Launch Live Agent\" above to watch each stage light up in real time.</span>\n                <code>IDLE</code>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ==================== PAGE 2: EXECUTIVE OVERVIEW ==================== -->\n      <section class=\"tab-section\" id=\"tab-overview\">\n        <div class=\"section-header\">\n          <div>\n            <h2>Executive Command Center</h2>\n            <p>Organization quantum readiness posture, cryptographic risk matrix, and NIST IR 8547 transition milestones.</p>\n          </div>\n          <button class=\"btn btn-outline btn-sm\" onclick=\"refreshAll()\">&#8635; Refresh</button>\n        </div>\n\n        <div class=\"kpi-grid\">\n          <div class=\"kpi-card kpi-blue\">\n            <div class=\"kpi-label\">Readiness Score (Before &rarr; After)</div>\n            <div class=\"kpi-value\" id=\"kpi-readiness\">0%</div>\n            <div class=\"kpi-sub\" id=\"kpi-net-readiness\">Network TLS: 0%</div>\n          </div>\n          <div class=\"kpi-card kpi-red\">\n            <div class=\"kpi-label\">Critical Findings</div>\n            <div class=\"kpi-value\" style=\"color:var(--red)\" id=\"kpi-critical\">0</div>\n            <div class=\"kpi-sub\">Broken or vulnerable classical KEX</div>\n          </div>\n          <div class=\"kpi-card kpi-red\">\n            <div class=\"kpi-label\">HNDL-Urgent Assets</div>\n            <div class=\"kpi-value\" style=\"color:var(--red)\" id=\"kpi-hndl\">0</div>\n            <div class=\"kpi-sub\">Secrecy + Migration &gt; CRQC years</div>\n          </div>\n          <div class=\"kpi-card kpi-green\">\n            <div class=\"kpi-label\">Auto-Fix Network Progress</div>\n            <div class=\"kpi-value\" style=\"color:var(--green)\" id=\"kpi-migration\">0%</div>\n            <div class=\"kpi-sub\" id=\"kpi-migration-sub\">0 / 0 plan items</div>\n          </div>\n          <div class=\"kpi-card kpi-purple\">\n            <div class=\"kpi-label\">PQC Certificates Issued</div>\n            <div class=\"kpi-value\" style=\"color:var(--purple)\" id=\"kpi-pqc-certs\">0</div>\n            <div class=\"kpi-sub\">ML-DSA-87 / ML-DSA-65 / SLH-DSA</div>\n          </div>\n          <div class=\"kpi-card kpi-blue\">\n            <div class=\"kpi-label\">Encrypted Vault Keys</div>\n            <div class=\"kpi-value\" id=\"kpi-keys-due\">0</div>\n            <div class=\"kpi-sub\" id=\"kpi-keys-sub\">AES-256-GCM (.enc) at rest</div>\n          </div>\n        </div>\n\n        <div class=\"grid-2\">\n          <div class=\"card\">\n            <h3>Asset Risk Matrix (Key Exchange \u00b7 Signature \u00b7 Symmetric \u00b7 Protocol)</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Asset / Endpoint</th>\n                    <th>Key Exchange</th>\n                    <th>Signature / Auth</th>\n                    <th>Symmetric / Hash</th>\n                    <th>Protocol</th>\n                  </tr>\n                </thead>\n                <tbody id=\"heatmap-tbody\">\n                  <tr><td colspan=\"5\">Click \"Launch Live Agent\" to populate the matrix.</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>3-Wave Migration Progress &amp; NIST IR 8547 Timeline</h3>\n            <div class=\"chart-box\" style=\"height:185px; margin-bottom:16px;\">\n              <canvas id=\"chart-overview-waves\"></canvas>\n            </div>\n            <div class=\"timeline\" style=\"font-size:0.8rem;\">\n              <div class=\"tl-item\">\n                <div class=\"tl-dot\"></div>\n                <b>Aug 2024 \u2014 FIPS 203 (ML-KEM), FIPS 204 (ML-DSA), FIPS 205 (SLH-DSA) Published</b>\n              </div>\n              <div class=\"tl-item today\">\n                <div class=\"tl-dot\"></div>\n                <b style=\"color:var(--green)\">TODAY (<span id=\"tl-today-date\">2026</span>) \u2014 Active Hybrid Rollout &amp; CBOM Window</b>\n              </div>\n              <div class=\"tl-item warn\">\n                <div class=\"tl-dot\"></div>\n                <b style=\"color:var(--purple)\">After 2030 \u2014 Classical RSA / ECDSA / ECDH Deprecated (NIST IR 8547)</b>\n              </div>\n              <div class=\"tl-item crit\" style=\"margin-bottom:0;\">\n                <div class=\"tl-dot\"></div>\n                <b style=\"color:var(--red)\">After 2035 \u2014 Classical Public-Key Algorithms Disallowed</b>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ==================== PAGE 3: DISCOVERY & MOSCA RISK ==================== -->\n      <section class=\"tab-section\" id=\"tab-discovery\">\n        <div class=\"section-header\">\n          <div>\n            <h2>Cryptographic Discovery, CBOM &amp; Mosca Risk Assessment</h2>\n            <p>Scan live TLS endpoints, source code, and X.509 certificates; evaluate HNDL urgency under NIST IR 8547.</p>\n          </div>\n          <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n            <button class=\"btn btn-outline btn-sm\" onclick=\"startEnterprise(true)\">Start / Reset 5 Services</button>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"stopEnterprise()\">Stop Services</button>\n            <button class=\"btn btn-blue btn-sm\" onclick=\"triggerScan('before')\">&#128269; Scan (\"Before\")</button>\n            <button class=\"btn btn-green btn-sm\" onclick=\"triggerScan('after')\">&#128269; Scan (\"After\")</button>\n          </div>\n        </div>\n\n        <div class=\"sub-nav\">\n          <button class=\"sub-btn active\" onclick=\"switchSubTab('discovery', 'sub-disc-services', this)\">Enterprise Services &amp; Assets (<span id=\"assets-count\">0</span>)</button>\n          <button class=\"sub-btn\" onclick=\"switchSubTab('discovery', 'sub-disc-risk', this)\">Mosca Risk Scoring &amp; Findings</button>\n          <button class=\"sub-btn\" onclick=\"switchSubTab('discovery', 'sub-disc-live', this)\">&#127760; Live Internet Scan</button>\n        </div>\n\n        <div class=\"sub-pane active\" id=\"sub-disc-services\">\n          <div class=\"card\">\n            <h3>Simulated Enterprise TLS Services (openssl s_server)</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Service Name</th>\n                    <th>Port</th>\n                    <th>Exposure</th>\n                    <th>Data Secrecy Shelf-Life</th>\n                    <th>Active TLS / PQC Profile</th>\n                    <th>State</th>\n                  </tr>\n                </thead>\n                <tbody id=\"enterprise-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>\n              <span>Discovered Cryptographic Inventory</span>\n              <select id=\"asset-source-filter\" style=\"width:190px;\" onchange=\"loadAssets()\">\n                <option value=\"all\">All Sources</option>\n                <option value=\"network\">Network TLS</option>\n                <option value=\"code\">Source Code</option>\n                <option value=\"certificate\">Certificates</option>\n                <option value=\"key\">Private Keys</option>\n              </select>\n            </h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>ID</th>\n                    <th>Source</th>\n                    <th>Location</th>\n                    <th>Algorithm</th>\n                    <th>Family</th>\n                    <th>Usage</th>\n                    <th>Protocol</th>\n                    <th>Details</th>\n                  </tr>\n                </thead>\n                <tbody id=\"assets-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"sub-pane\" id=\"sub-disc-risk\">\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <h3>Mosca Shelf-Life Assumptions (X + Y &gt; Z &rArr; HNDL Urgent)</h3>\n              <p style=\"font-size:0.82rem; color:var(--text-muted); margin-bottom:14px;\">\n                Key-exchange assets are flagged <b>HNDL Urgent</b> when <code>data_secrecy_years + migration_years &gt; years_to_crqc</code>.\n              </p>\n              <div class=\"slider-group\">\n                <label>\n                  <span>Estimated Years to Quantum Computer (Z):</span>\n                  <b id=\"lbl-crqc\" style=\"color:var(--purple)\">10 years</b>\n                </label>\n                <input type=\"range\" id=\"slider-crqc\" min=\"3\" max=\"25\" value=\"10\" oninput=\"document.getElementById('lbl-crqc').textContent=this.value+' years'\" onchange=\"updateAssumptions()\" />\n              </div>\n              <div class=\"slider-group\">\n                <label>\n                  <span>Enterprise Migration Duration (Y):</span>\n                  <b id=\"lbl-mig\" style=\"color:var(--blue)\">3 years</b>\n                </label>\n                <input type=\"range\" id=\"slider-mig\" min=\"1\" max=\"10\" value=\"3\" oninput=\"document.getElementById('lbl-mig').textContent=this.value+' years'\" onchange=\"updateAssumptions()\" />\n              </div>\n            </div>\n\n            <div class=\"card\">\n              <h3>Severity Distribution</h3>\n              <div class=\"chart-box\" style=\"height:185px;\">\n                <canvas id=\"chart-risk-severity\"></canvas>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>Vulnerability Findings &amp; NIST IR 8547 Status</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Asset Location</th>\n                    <th>Source / Usage</th>\n                    <th>Algorithm</th>\n                    <th>Score &amp; Severity</th>\n                    <th>HNDL Status</th>\n                    <th>NIST IR 8547 Status</th>\n                    <th>Assessment Rationale</th>\n                  </tr>\n                </thead>\n                <tbody id=\"findings-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"sub-pane\" id=\"sub-disc-live\">\n          <div class=\"card\">\n            <h3>\n              <span>Is This Website Quantum-Ready? (Live Internet TLS 1.3 PQC Scanner)</span>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"runLiveScanAll()\">Scan All Suggestions</button>\n            </h3>\n            <div style=\"display:flex; gap:10px; align-items:center; flex-wrap:wrap;\">\n              <input type=\"text\" id=\"live-host\" placeholder=\"e.g. cloudflare.com or yourbank.com\" style=\"max-width:360px;\" onkeydown=\"if(event.key==='Enter')runLiveScan()\" />\n              <button class=\"btn btn-purple\" id=\"btn-live-scan\" onclick=\"runLiveScan()\">&#127760; Scan Live</button>\n            </div>\n            <div id=\"live-suggestions\" style=\"margin-top:10px; display:flex; gap:6px; flex-wrap:wrap;\"></div>\n            <p style=\"color:var(--text-muted); font-size:0.78rem; margin-top:8px;\">Only public hostnames on port 443 are accepted. Verified against the Mozilla trust store; detects TLS interception proxies.</p>\n          </div>\n          <div id=\"live-result\" style=\"margin-bottom:14px;\"></div>\n          <div class=\"card\">\n            <h3>Scanned Public Websites This Session</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead><tr><th>Website</th><th>Verdict</th><th>Key Exchange (PQC Client)</th><th>Certificate</th><th>TLS 1.2 Accepted</th><th>Measured (UTC)</th></tr></thead>\n                <tbody id=\"live-history\"><tr><td colspan=\"6\" style=\"color:var(--text-muted);\">No public websites scanned yet.</td></tr></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ==================== PAGE 4: MIGRATION, PKI & KEY VAULT ==================== -->\n      <section class=\"tab-section\" id=\"tab-migration\">\n        <div class=\"section-header\">\n          <div>\n            <h2>Post-Quantum Migration Planner, PKI &amp; Key Vault</h2>\n            <p>Execute 3-wave migration plans, manage Classical/ML-DSA/SLH-DSA CAs, demonstrate dual-cert serving, and inspect AES-256-GCM encrypted keys.</p>\n          </div>\n          <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n            <button class=\"btn btn-outline btn-sm\" onclick=\"buildPlan()\">Build Plan</button>\n            <button class=\"btn btn-green btn-sm\" onclick=\"applyMigrationPlan()\">&#9889; Apply Auto-Fixable Network Items</button>\n            <button class=\"btn btn-purple btn-sm\" onclick=\"runDualCertDemo()\">&#9889; Run Dual-Certificate Demo</button>\n          </div>\n        </div>\n\n        <div class=\"sub-nav\">\n          <button class=\"sub-btn active\" onclick=\"switchSubTab('migration', 'sub-mig-plan', this)\">1. 3-Wave Plan &amp; Before/After</button>\n          <button class=\"sub-btn\" onclick=\"switchSubTab('migration', 'sub-mig-pki', this)\">2. PKI CAs &amp; Dual-Cert Serving</button>\n          <button class=\"sub-btn\" onclick=\"switchSubTab('migration', 'sub-mig-vault', this)\">3. Encrypted Key Vault &amp; Audit Log</button>\n        </div>\n\n        <div class=\"sub-pane active\" id=\"sub-mig-plan\">\n          <div class=\"card\">\n            <h3>Auto-Applicable Network Migration Progress (<span id=\"plan-progress-lbl\">0%</span>)</h3>\n            <div class=\"progress-outer\">\n              <div class=\"progress-inner\" id=\"plan-progress-bar\" style=\"width:0%\"></div>\n            </div>\n          </div>\n\n          <div class=\"card\" id=\"compare-card\">\n            <h3>Before vs. After Migration Verification</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Asset Location</th>\n                    <th>Usage</th>\n                    <th>Before Algorithm</th>\n                    <th>After Algorithm</th>\n                    <th>Severity Change</th>\n                    <th>Score Change</th>\n                  </tr>\n                </thead>\n                <tbody id=\"compare-tbody\">\n                  <tr><td colspan=\"6\">Click \"Apply Auto-Fixable Network Items\" to reconfigure services and verify improvement.</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>Prioritized Migration Roadmap (Waves 1, 2 &amp; 3)</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Rank / Wave</th>\n                    <th>Location</th>\n                    <th>Current</th>\n                    <th>Recommended Target &amp; Standard</th>\n                    <th>Effort</th>\n                    <th>Rationale &amp; Crypto-Agility Guidance</th>\n                    <th>Status</th>\n                  </tr>\n                </thead>\n                <tbody id=\"plan-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"sub-pane\" id=\"sub-mig-pki\">\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <h3>\n                <span>Dual-Certificate Serving Proof (Same Server, Legacy vs. PQC Client)</span>\n                <button class=\"btn btn-purple btn-sm\" onclick=\"runDualCertDemo()\">Run Demo</button>\n              </h3>\n              <p style=\"font-size:0.81rem; color:var(--text-muted); margin-bottom:12px;\">\n                Server runs <code>openssl s_server -cert classical.crt -dcert pqc_mldsa65.crt -groups X25519MLKEM768:X25519</code>.\n              </p>\n              <div class=\"grid-2\" id=\"dual-cert-cards\" style=\"grid-template-columns:1fr 1fr; gap:12px; margin-bottom:0;\">\n                <div class=\"kpi-card kpi-blue\">\n                  <div class=\"kpi-label\">Client A: Classical Restricted</div>\n                  <div id=\"dc-old-body\" style=\"font-size:0.82rem; margin-top:8px; color:var(--text-secondary);\">Click \"Run Demo\"</div>\n                </div>\n                <div class=\"kpi-card kpi-green\">\n                  <div class=\"kpi-label\">Client B: PQC-Capable Default</div>\n                  <div id=\"dc-new-body\" style=\"font-size:0.82rem; margin-top:8px; color:var(--text-secondary);\">Click \"Run Demo\"</div>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"card\">\n              <h3>\n                <span>Issue Leaf Certificate &amp; Rotate Services</span>\n                <button class=\"btn btn-outline btn-sm\" onclick=\"initPKI()\">Init Root CAs</button>\n              </h3>\n              <div style=\"display:flex; gap:8px; margin-bottom:12px;\">\n                <input type=\"text\" id=\"pki-issue-name\" placeholder=\"Leaf name\" value=\"billing-svc\" />\n                <select id=\"pki-issue-alg\">\n                  <option value=\"ML-DSA-65\">ML-DSA-65 (PQC Root CA)</option>\n                  <option value=\"ECDSA-P256\">ECDSA-P256 (Classical Root CA)</option>\n                </select>\n                <button class=\"btn btn-blue btn-sm\" onclick=\"issueCertUI()\">Issue</button>\n              </div>\n              <div id=\"cert-size-comparison\" style=\"font-size:0.83rem; color:var(--text-secondary); margin-bottom:10px;\"></div>\n              <div style=\"display:flex; gap:6px; flex-wrap:wrap;\">\n                <button class=\"btn btn-outline btn-sm\" onclick=\"rotateServiceCert('legacy-web')\">Rotate legacy-web</button>\n                <button class=\"btn btn-outline btn-sm\" onclick=\"rotateServiceCert('customer-api')\">Rotate customer-api</button>\n                <button class=\"btn btn-outline btn-sm\" onclick=\"rotateServiceCert('payments-core')\">Rotate payments-core</button>\n                <button class=\"btn btn-outline btn-sm\" onclick=\"rotateServiceCert('hr-records')\">Rotate hr-records</button>\n                <button class=\"btn btn-outline btn-sm\" onclick=\"rotateServiceCert('pqc-pilot')\">Rotate pqc-pilot</button>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>Certificate Inventory &amp; Chain Verification</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>ID</th>\n                    <th>Name</th>\n                    <th>Issuing CA</th>\n                    <th>Key Algorithm</th>\n                    <th>Signature Algorithm</th>\n                    <th>DER Size</th>\n                    <th>Valid Until</th>\n                    <th>Status</th>\n                    <th>Verify Chain</th>\n                  </tr>\n                </thead>\n                <tbody id=\"pki-certs-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"sub-pane\" id=\"sub-mig-vault\">\n          <div class=\"card\" style=\"border-left: 4px solid var(--purple);\">\n            <div id=\"vault-notice\" style=\"font-size:0.84rem; font-weight:600; color:var(--text-secondary);\">\n              All private keys live on disk exclusively as AES-256-GCM ciphertext (<code>.key.enc</code>, chmod 600). Plaintext keys are materialized only for active OpenSSL operations and immediately wiped.\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>Encrypted Key Inventory</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>ID</th>\n                    <th>Key Name</th>\n                    <th>Algorithm</th>\n                    <th>Purpose</th>\n                    <th>Created At</th>\n                    <th>Rotate By</th>\n                    <th>At-Rest Encryption</th>\n                    <th>Status</th>\n                    <th>Action</th>\n                  </tr>\n                </thead>\n                <tbody id=\"vault-keys-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>Immutable Cryptographic Audit Log</h3>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>ID</th>\n                    <th>Timestamp (UTC)</th>\n                    <th>Actor</th>\n                    <th>Action</th>\n                    <th>Target</th>\n                    <th>Detail</th>\n                  </tr>\n                </thead>\n                <tbody id=\"audit-tbody\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ==================== PAGE 5: CRYPTO LAB & BENCHMARKS ==================== -->\n      <section class=\"tab-section\" id=\"tab-hybrid\">\n        <div class=\"section-header\">\n          <div>\n            <h2>Hybrid Encryption Lab, TLS Policy Tests &amp; Empirical Benchmarks</h2>\n            <p>Interactive X25519 + ML-KEM-768 combiner, live TLS 1.3 policy probes, and fair in-process <code>openssl speed</code> benchmarks.</p>\n          </div>\n        </div>\n\n        <div class=\"sub-nav\">\n          <button class=\"sub-btn active\" onclick=\"switchSubTab('hybrid', 'sub-lab-combiner', this)\">1. Hybrid KEM Combiner &amp; TLS Policy Tests</button>\n          <button class=\"sub-btn\" onclick=\"switchSubTab('hybrid', 'sub-lab-bench', this)\">2. Performance &amp; Size Benchmarks</button>\n        </div>\n\n        <div class=\"sub-pane active\" id=\"sub-lab-combiner\">\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <h3>Application-Level Hybrid KEM Demo (X25519 + ML-KEM-768 &rarr; HKDF &rarr; AES-256-GCM)</h3>\n              <div style=\"margin-bottom:10px;\">\n                <label style=\"font-size:0.8rem; color:var(--text-muted); font-weight:600;\">Plaintext Payload:</label>\n                <input type=\"text\" id=\"hybrid-msg\" value=\"SWIFT Wire #9941: Transfer $25,000,000 \u2014 Protect against Harvest-Now-Decrypt-Later\" style=\"margin-top:4px;\" />\n              </div>\n              <div style=\"display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-bottom:14px;\">\n                <select id=\"hybrid-mode\" style=\"width:240px;\">\n                  <option value=\"hybrid\">Hybrid Mode (X25519 + ML-KEM-768)</option>\n                  <option value=\"classical\">Classical-Only Mode (X25519 Alone)</option>\n                </select>\n                <label style=\"font-size:0.8rem; color:var(--text-secondary); display:flex; align-items:center; gap:5px; cursor:pointer;\">\n                  <input type=\"checkbox\" id=\"hybrid-tamper\" /> Tamper ciphertext (test GCM auth)\n                </label>\n                <button class=\"btn btn-purple btn-sm\" onclick=\"runHybridLab()\">&#128274; Encrypt &amp; Verify</button>\n              </div>\n              <div id=\"hybrid-summary-box\"></div>\n              <div id=\"hybrid-steps-list\" style=\"margin-top:12px;\"></div>\n            </div>\n\n            <div class=\"card\">\n              <h3>\n                <span>TLS 1.3 Policy Verification (Fallback \u00b7 Strict PQC \u00b7 Hybrid)</span>\n                <button class=\"btn btn-blue btn-sm\" onclick=\"runPolicyTestsUI()\">&#9654; Run 3 Policy Tests</button>\n              </h3>\n              <div id=\"policy-tests-container\">\n                <p style=\"color:var(--text-muted); font-size:0.83rem;\">Click \"Run 3 Policy Tests\" to verify Classical Fallback, Strict PQC-Only Rejection, and Hybrid Negotiation.</p>\n              </div>\n\n              <h3 style=\"margin-top:18px;\">Why Hybrid Combiners Defeat \"Harvest Now, Decrypt Later\"</h3>\n              <div id=\"hndl-explanation-box\" style=\"font-size:0.83rem; color:var(--text-secondary); background:#f8fafc; border:1px solid var(--glass-outline); padding:12px; border-radius:12px;\">\n                Run the Hybrid KEM demo on the left to inspect transcript overhead and SHA-256 shared-secret fingerprints.\n              </div>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <h3>\n              <span>&#9200; Q-Day Replay: Harvest Now, Decrypt Later Simulation</span>\n              <button class=\"btn btn-purple btn-sm\" onclick=\"runQDay()\">&#9654; Record Today, Attack at Q-Day</button>\n            </h3>\n            <p style=\"color:var(--text-muted); font-size:0.8rem; margin-bottom:8px;\">An eavesdropper records both a classical X25519 session and a hybrid X25519 + ML-KEM-768 session today. At Q-Day, a quantum computer recovers the X25519 secret key via Shor&rsquo;s algorithm. Which recording can it read?</p>\n            <input type=\"text\" id=\"qday-msg\" value=\"Patient record #4471: diagnosis confidential until 2051\" style=\"margin-bottom:10px;\" />\n            <div id=\"qday-result\"></div>\n          </div>\n        </div>\n\n        <div class=\"sub-pane\" id=\"sub-lab-bench\">\n          <div class=\"card\">\n            <h3>\n              <span>Computed Key Takeaways &amp; Host Specifications</span>\n              <div style=\"display:flex; gap:8px; align-items:center;\">\n                <input type=\"text\" id=\"bench-n\" value=\"30\" style=\"width:70px;\" title=\"Iterations\" />\n                <button class=\"btn btn-purple btn-sm\" id=\"btn-run-bench\" onclick=\"triggerBenchmarks()\">&#9201; Run Live Benchmarks</button>\n                <a class=\"btn btn-outline btn-sm\" id=\"btn-bench-csv\" href=\"#\" target=\"_blank\">&#11015; CSV</a>\n              </div>\n            </h3>\n            <div id=\"bench-machine-info\" style=\"font-size:0.8rem; color:var(--text-muted); margin-bottom:8px;\"></div>\n            <ul id=\"bench-takeaways\" style=\"padding-left:20px; font-size:0.84rem; color:var(--text-secondary);\"></ul>\n          </div>\n\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <h3>Primary Fair Latency: In-Process <code>openssl speed</code> (ms/op \u2014 Log Scale)</h3>\n              <div class=\"chart-box\">\n                <canvas id=\"chart-bench-latency\"></canvas>\n              </div>\n            </div>\n            <div class=\"card\">\n              <h3>Exact Public Key vs. Ciphertext / Signature Size (Bytes \u2014 Log Scale)</h3>\n              <div class=\"chart-box\">\n                <canvas id=\"chart-bench-sizes\"></canvas>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <h3>Primary Table: In-Process <code>openssl speed</code> (Same C Engine)</h3>\n              <div class=\"table-wrap\">\n                <table>\n                  <thead>\n                    <tr>\n                      <th>Algorithm &amp; Operation</th>\n                      <th>Category</th>\n                      <th>Throughput</th>\n                      <th>Latency</th>\n                      <th>p95</th>\n                      <th>CPU</th>\n                      <th>PubKey</th>\n                      <th>CT / Sig</th>\n                      <th>Method</th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"bench-tbody\"></tbody>\n                </table>\n              </div>\n            </div>\n\n            <div class=\"card\">\n              <h3>Secondary Table: End-to-End TLS 1.3 &amp; Python <code>cryptography</code></h3>\n              <div class=\"table-wrap\">\n                <table>\n                  <thead>\n                    <tr>\n                      <th>Operation / Profile</th>\n                      <th>Category</th>\n                      <th>N</th>\n                      <th>Median</th>\n                      <th>p95</th>\n                      <th>CPU</th>\n                      <th>PubKey</th>\n                      <th>Wire</th>\n                      <th>Notes</th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"bench-secondary-tbody\"></tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <!-- ==================== GLASSMORPHIC AUTH & RBAC MODAL (SUPABASE BACKED) ==================== -->\n  <div id=\"auth-modal\" style=\"display:none; position:fixed; inset:0; z-index:9000; background:rgba(15,23,42,0.38); backdrop-filter:blur(10px); align-items:center; justify-content:center; padding:16px;\">\n    <div style=\"background:#ffffff; border:1.5px solid var(--purple); border-radius:20px; width:100%; max-width:440px; padding:24px; box-shadow:0 24px 60px rgba(15,23,42,0.22); position:relative;\">\n      <button onclick=\"closeAuthModal()\" style=\"position:absolute; top:14px; right:16px; background:#fff; border:1px solid #cbd5e1; border-radius:8px; width:28px; height:28px; cursor:pointer; font-weight:800; color:#64748b;\">&times;</button>\n      <div style=\"display:flex; align-items:center; gap:10px; margin-bottom:6px;\">\n        <div class=\"brand-orb\" style=\"width:32px; height:32px; font-size:0.8rem;\">QG</div>\n        <div>\n          <h3 style=\"font-size:1.05rem; font-weight:800; margin:0;\">Quantum Guard SaaS Identity</h3>\n          <div style=\"font-size:0.72rem; color:var(--text-muted);\">quantumguard-lab.veerbhanushali.in \u00b7 Supabase Cloud</div>\n        </div>\n      </div>\n      <p id=\"auth-modal-reason\" style=\"font-size:0.78rem; color:var(--purple); font-weight:600; margin-bottom:12px;\">\n        Sign in or create a free account to unlock full Executive PDF Reports &amp; Resend email delivery.\n      </p>\n\n      <div class=\"sub-nav\" style=\"width:100%; display:flex; margin-bottom:14px;\">\n        <button class=\"sub-btn active\" id=\"tab-btn-login\" style=\"flex:1;\" onclick=\"switchAuthTab('login')\">Sign In</button>\n        <button class=\"sub-btn\" id=\"tab-btn-register\" style=\"flex:1;\" onclick=\"switchAuthTab('register')\">Create Account (RBAC)</button>\n      </div>\n\n      <!-- Sign In Form -->\n      <div id=\"auth-form-login\">\n        <div style=\"margin-bottom:10px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Work or Personal Email</label>\n          <input type=\"text\" id=\"login-email\" placeholder=\"you@company.com\" style=\"margin-top:4px;\" />\n        </div>\n        <div style=\"margin-bottom:14px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Password</label>\n          <input type=\"password\" id=\"login-password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" style=\"width:100%; background:#fff; border:1.5px solid #cbd5e1; padding:7px 11px; border-radius:9px; margin-top:4px;\" onkeydown=\"if(event.key==='Enter')submitLogin()\" />\n        </div>\n        <button class=\"btn btn-purple\" style=\"width:100%; padding:10px;\" onclick=\"submitLogin()\">&#128274; Sign In &amp; Unlock Reports</button>\n      </div>\n\n      <!-- Sign Up Form with Role Selection -->\n      <div id=\"auth-form-register\" style=\"display:none;\">\n        <div style=\"margin-bottom:8px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Full Name</label>\n          <input type=\"text\" id=\"reg-name\" placeholder=\"Veer Bhanushali\" style=\"margin-top:3px;\" />\n        </div>\n        <div style=\"margin-bottom:8px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Organization / Company</label>\n          <input type=\"text\" id=\"reg-org\" placeholder=\"Acme FinTech / Hospital\" style=\"margin-top:3px;\" />\n        </div>\n        <div style=\"margin-bottom:8px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Enterprise Role (RBAC)</label>\n          <select id=\"reg-role\" style=\"margin-top:3px;\">\n            <option value=\"ciso\">CISO / Executive Viewer (Read &amp; Reports)</option>\n            <option value=\"secops\">SecOps / Discovery Analyst (Scan &amp; CBOM)</option>\n            <option value=\"pki_admin\">PKI &amp; Crypto Administrator (Full Auto-Migrate &amp; CA)</option>\n            <option value=\"auditor\">Compliance Auditor (NIST IR 8547 &amp; Audit Trail)</option>\n          </select>\n        </div>\n        <div style=\"margin-bottom:8px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Email Address (For Resend Report Delivery)</label>\n          <input type=\"text\" id=\"reg-email\" placeholder=\"you@company.com\" style=\"margin-top:3px;\" />\n        </div>\n        <div style=\"margin-bottom:14px;\">\n          <label style=\"font-size:0.75rem; font-weight:700; color:var(--text-secondary);\">Password (min 6 chars)</label>\n          <input type=\"password\" id=\"reg-password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" style=\"width:100%; background:#fff; border:1.5px solid #cbd5e1; padding:7px 11px; border-radius:9px; margin-top:3px;\" onkeydown=\"if(event.key==='Enter')submitRegister()\" />\n        </div>\n        <button class=\"btn btn-green\" style=\"width:100%; padding:10px;\" onclick=\"submitRegister()\">&#10024; Create Account in Supabase &amp; Unlock</button>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"toast-container\"></div>";
export default function QuantumGuardPage() { return <div id='nextjs-quantumguard-root' suppressHydrationWarning dangerouslySetInnerHTML={{ __html: WORKSPACE_HTML }} />; }
